def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the horizontal separator rows of the framed pattern.
    bg = max(set(grid[0]), key=grid[0].count)
    sep = [r for r, row in enumerate(grid) if all(v == bg for v in row)]
    panels = [(sep[i] + 1, sep[i + 1]) for i in range(len(sep) - 1)]

    # The colored objects occupy the right-hand portion; collect their colors
    # in top-to-bottom order.
    colors = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (0, bg) and grid[r][c] not in colors:
                colors.append(grid[r][c])

    # Keep the frame and color the holes in each framed panel.
    out = [row[:] for row in grid]
    for i, (a, b) in enumerate(panels):
        color = colors[i % len(colors)] if colors else bg
        for r in range(a, b):
            for c in range(w):
                if grid[r][c] == 0 and c < w // 2:
                    out[r][c] = color
    return [row[:w // 2] for row in out]
