def transform(grid):
    h, w = len(grid), len(grid[0])
    frame = grid[0][0]
    mid = w // 2

    def normalize(points):
        r0 = min(r for r, c in points)
        c0 = min(c for r, c in points)
        return frozenset((r-r0, c-c0) for r, c in points)

    # Shapes of the colored objects on the right.
    shapes = {}
    for color in set(v for row in grid for v in row):
        if color in (0, frame):
            continue
        points = [(r, c) for r in range(h) for c in range(mid, w)
                  if grid[r][c] == color]
        if points:
            shapes[normalize(points)] = color

    separators = [r for r in range(h)
                  if all(v == frame for v in grid[r][:mid])]
    out = [row[:mid] for row in grid]

    for top, bottom in zip(separators, separators[1:]):
        holes = [(r, c) for r in range(top+1, bottom)
                 for c in range(1, mid-1) if grid[r][c] == 0]
        if not holes:
            continue
        color = shapes.get(normalize(holes))
        if color is not None:
            for r, c in holes:
                out[r][c] = color

    return out
